1	import { NextRequest, NextResponse } from 'next/server';
2	
3	const BOT_GATEWAY_URL =
4	  process.env.BOT_GATEWAY_URL ||
5	  process.env.NEXT_PUBLIC_BOT_CONTROL_BASE_URL ||
6	  'http://localhost:4444';
7	
8	/**
9	 * Proxy /api/image?q=SUBJECT to the bot gateway's image resolver.
10	 * This allows the Wonder Canvas iframe (running on the client) to fetch
11	 * images without needing direct access to localhost:4444.
12	 */
13	export async function GET(request: NextRequest) {
14	  const q = request.nextUrl.searchParams.get('q');
15	  if (!q) {
16	    return NextResponse.json({ error: 'Missing q parameter' }, { status: 400 });
17	  }
18	
19	  try {
20	    const upstream = await fetch(
21	      `${BOT_GATEWAY_URL}/api/image?q=${encodeURIComponent(q)}`,
22	      { redirect: 'follow' },
23	    );
24	
25	    const contentType = upstream.headers.get('content-type') || 'image/jpeg';
26	    const body = await upstream.arrayBuffer();
27	
28	    return new NextResponse(body, {
29	      status: 200,
30	      headers: {
31	        'Content-Type': contentType,
32	        'Cache-Control': 'public, max-age=86400',
33	        'Access-Control-Allow-Origin': '*',
34	      },
35	    });
36	  } catch (err) {
37	    console.error('[api/image] proxy error:', err);
38	    return NextResponse.json({ error: 'Image fetch failed' }, { status: 502 });
39	  }
40	}
