1	'use client';
2	
3	import React, { useEffect, useState, useCallback, useRef } from 'react';
4	
5	interface GalleryItem {
6	  filename: string;
7	  url: string;
8	  created: number;
9	  size: number;
10	}
11	
12	export const PhotoGallery: React.FC<{
13	  onSelectImage?: (url: string, filename: string) => void;
14	  /** Which card shows focus ring (usually set by parent when that image is loaded as the active file) */
15	  selectedFilename?: string | null;
16	}> = ({ onSelectImage, selectedFilename = null }) => {
17	  const [items, setItems] = useState<GalleryItem[]>([]);
18	  const [loading, setLoading] = useState(true);
19	  const [expanded, setExpanded] = useState<string | null>(null);
20	  const scrollRef = useRef<HTMLDivElement>(null);
21	  const [canScrollLeft, setCanScrollLeft] = useState(false);
22	  const [canScrollRight, setCanScrollRight] = useState(false);
23	
24	  const load = useCallback(async () => {
25	    try {
26	      const res = await fetch('/bot-api/photo-magic/gallery');
27	      if (res.ok) {
28	        const data = await res.json();
29	        setItems(data.items || []);
30	      }
31	    } catch { /* silent */ }
32	    setLoading(false);
33	  }, []);
34	
35	  useEffect(() => { load(); }, [load]);
36	
37	  const updateScrollButtons = useCallback(() => {
38	    const el = scrollRef.current;
39	    if (!el) return;
40	    setCanScrollLeft(el.scrollLeft > 4);
41	    setCanScrollRight(el.scrollLeft < el.scrollWidth - el.clientWidth - 4);
42	  }, []);
43	
44	  useEffect(() => {
45	    updateScrollButtons();
46	    const el = scrollRef.current;
47	    if (!el) return;
48	    el.addEventListener('scroll', updateScrollButtons, { passive: true });
49	    const onResize = () => updateScrollButtons();
50	    window.addEventListener('resize', onResize, { passive: true });
51	    window.addEventListener('orientationchange', onResize);
52	    return () => {
53	      el.removeEventListener('scroll', updateScrollButtons);
54	      window.removeEventListener('resize', onResize);
55	      window.removeEventListener('orientationchange', onResize);
56	    };
57	  }, [items.length, updateScrollButtons]);
58	
59	  const scrollStrip = (dir: number) => {
60	    scrollRef.current?.scrollBy({ left: dir * 220, behavior: 'smooth' });
61	  };
62	
63	  if (loading) {
64	    return (
65	      <div style={{ padding: '24px', textAlign: 'center', color: 'rgba(255,255,255,0.3)', fontFamily: 'Gohufont, monospace', fontSize: 11, textTransform: 'uppercase', letterSpacing: 2 }}>
66	        Loading gallery...
67	      </div>
68	    );
